194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        HttpHeaders headers = new HttpHeaders();
202	        Pet pet = petMapper.toPet(petFieldsDto);
203	        owner.setId(ownerId);
204	        pet.setOwner(owner);
205	        pet.getType().setName(null);
206	        this.clinicService.savePet(pet);
207	        PetDto petDto = petMapper.toPetDto(pet);
208	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
209	            .buildAndExpand(pet.getId()).toUri());
210	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
211	    }
